import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  city: string;
  street: string;
  comment: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    name: '',
    email: '',
    city: '',
    street: '',
    comment: '',
  });

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const emailError =
    data.email.length > 0 && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const contactsReady = data.name.trim().length > 0 && data.email.includes('@');
  const addressReady = data.city.trim().length > 0 && data.street.trim().length > 0;
  const canGoNext = step === 0 ? contactsReady : step === 1 ? addressReady : true;

  return (
    <div style={{ display: 'grid', gap: '20px', fontFamily: 'var(--jx-font-sans)', color: 'var(--jx-text)' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            autoComplete="name"
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            required
            autoComplete="street-address"
            value={data.street}
            onChange={(event) => set('street', event.target.value)}
          />
          <JxTextareaField
            label="Комментарий к доставке"
            rows={3}
            maxLength={300}
            value={data.comment}
            onChange={(event) => set('comment', event.target.value)}
            helperText={`${data.comment.length}/300`}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'grid', gap: '8px' }}>
          <JxDivider label="Контакты" />
          <div style={{ display: 'grid', gap: '4px' }}>
            <span style={{ color: 'var(--jx-text-2)' }}>Имя</span>
            <span>{data.name}</span>
            <span style={{ color: 'var(--jx-text-2)' }}>Почта</span>
            <span>{data.email}</span>
          </div>
          <JxDivider label="Адрес" />
          <div style={{ display: 'grid', gap: '4px' }}>
            <span style={{ color: 'var(--jx-text-2)' }}>Город</span>
            <span>{data.city}</span>
            <span style={{ color: 'var(--jx-text-2)' }}>Улица и дом</span>
            <span>{data.street}</span>
            {data.comment && (
              <>
                <span style={{ color: 'var(--jx-text-2)' }}>Комментарий</span>
                <span>{data.comment}</span>
              </>
            )}
          </div>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext} onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

